import zlib, bz2, lzma

def enc(x):
    x = bytes(x)
    candidates = [(b'\x00' + x, 0)]
    for tag, fn in ((1, zlib.compress), (2, bz2.compress), (3, lzma.compress)):
        try:
            candidates.append((bytes((tag,)) + fn(x), tag))
        except Exception:
            pass
    return min(candidates, key=lambda p: len(p[0]))[0]

def dec(data):
    data = bytes(data)
    if not data:
        raise ValueError('invalid encoding')
    tag, payload = data[0], data[1:]
    if tag == 0:
        return payload
    if tag == 1:
        return zlib.decompress(payload)
    if tag == 2:
        return bz2.decompress(payload)
    if tag == 3:
        return lzma.decompress(payload)
    raise ValueError('invalid encoding')

