import zlib, bz2, lzma

# A leading zero introduces an unambiguous framed representation. Other raw
# inputs use the identity representation, so incompressible data has no cost.
def enc(x):
    x = bytes(x)
    raw = (b'\x00\x00' + x) if x.startswith(b'\x00') else x
    best = raw
    for tag, fn in ((1, zlib.compress), (2, bz2.compress), (3, lzma.compress)):
        try:
            candidate = b'\x00' + bytes((tag,)) + fn(x)
            if len(candidate) < len(best):
                best = candidate
        except Exception:
            pass
    return best

def dec(data):
    data = bytes(data)
    if not data or data[0] != 0:
        return data
    if len(data) < 2:
        raise ValueError('invalid encoding')
    tag, payload = data[1], data[2:]
    if tag == 0:
        return data[2:]
    if tag == 1:
        return zlib.decompress(payload)
    if tag == 2:
        return bz2.decompress(payload)
    if tag == 3:
        return lzma.decompress(payload)
    raise ValueError('invalid encoding')

encode = enc
decode = dec

import zlib, bz2, lzma

_ESCAPE = b'\x00RAW\xff'

def _unpack(data):
    # Streams emitted by the compressors below are self-identifying.
    try:
        if data.startswith(b'BZh'):
            return bz2.decompress(data)
        if data.startswith(b'\xfd7zXZ\x00'):
            return lzma.decompress(data)
        if len(data) >= 2:
            cmf, flg = data[0], data[1]
            if (cmf & 15) == 8 and (cmf >> 4) <= 7 and ((cmf << 8) + flg) % 31 == 0:
                return zlib.decompress(data)
    except Exception:
        pass
    return None

def enc(x):
    x = bytes(x)
    raw = _ESCAPE + x if x.startswith(_ESCAPE) or _unpack(x) is not None else x
    best = raw
    for fn in (zlib.compress, bz2.compress, lzma.compress):
        try:
            c = fn(x)
            if len(c) < len(best):
                best = c
        except Exception:
            pass
    return best

def dec(data):
    data = bytes(data)
    if data.startswith(_ESCAPE):
        return data[len(_ESCAPE):]
    x = _unpack(data)
    return data if x is None else x

encode = enc
decode = dec
